1	// 権限の判定はここに集約する。ルート側で role を直接見ないこと。
2	const RULES = {
3	  read: ['admin', 'owner', 'editor', 'viewer'],
4	  update: ['admin', 'owner', 'editor'],
5	  invite: ['admin', 'owner'],
6	}
7	
8	export function roleIn(user, project) {
9	  if (user.isAdmin) return 'admin'
10	  return project.members.find((m) => m.userId === user.id)?.role ?? null
11	}
12	
13	export function can(user, action, project) {
14	  const role = roleIn(user, project)
15	  return Boolean(role && RULES[action]?.includes(role))
16	}
17

