18	
19	export function fakeProjects(p = project()) {
20	  const calls = []
21	  return {
22	    calls,
23	    get: async () => p,
24	    update: async (id, body) => (calls.push(['update', id]), { ...p, ...body }),
25	    remove: async (id) => calls.push(['remove', id]),
26	    archive: async (id) => calls.push(['archive', id]),
27	  }
28	}
