import { test } from 'node:test'
import assert from 'node:assert/strict'
import { updateProject, deleteProject, archiveProject } from '../src/routes/projects.js'
import { admin, owner, editor, viewer, stranger, fakeProjects } from './fixtures/users.js'

test('editor は更新できる', async () => {
  const res = await updateProject({ params: { id: 'p1' }, user: editor, body: { name: 'x' } }, { projects: fakeProjects() })
  assert.equal(res.status, 200)
})

test('viewer は更新できない', async () => {
  const res = await updateProject({ params: { id: 'p1' }, user: viewer, body: {} }, { projects: fakeProjects() })
  assert.equal(res.status, 403)
})

test('admin は削除できる', async () => {
  const res = await deleteProject({ params: { id: 'p1' }, user: admin }, { projects: fakeProjects() })
  assert.equal(res.status, 204)
})

test('owner は削除できる', async () => {
  const res = await deleteProject({ params: { id: 'p1' }, user: owner }, { projects: fakeProjects() })
  assert.equal(res.status, 204)
})

